"""Load the operator-supplied YAML configuration file."""

import argparse
from collections.abc import Sequence
from pathlib import Path

import yaml

MAX_CONFIG_BYTES = 1_000_000


class ConfigError(Exception):
    """The configuration file is missing, unreadable, or malformed."""


def load_config(path: Path) -> dict[str, object]:
    """Read a YAML mapping from path.

    The path is operator-supplied and trusted, but the contents are parsed with
    ``yaml.safe_load`` so a config file can never construct arbitrary Python
    objects, and the file size is bounded before parsing.
    """
    try:
        with path.open("rb") as handle:
            raw = handle.read(MAX_CONFIG_BYTES + 1)
    except OSError as exc:
        msg = f"cannot read config file {path}: {exc.strerror}"
        raise ConfigError(msg) from exc
    if len(raw) > MAX_CONFIG_BYTES:
        msg = f"config file {path} exceeds {MAX_CONFIG_BYTES} bytes"
        raise ConfigError(msg)

    try:
        data = yaml.safe_load(raw)
    except yaml.YAMLError as exc:
        msg = f"config file {path} is not valid YAML"
        raise ConfigError(msg) from exc

    if data is None:
        return {}
    if not isinstance(data, dict):
        msg = f"config file {path} must contain a mapping at the top level"
        raise ConfigError(msg)
    return data


def parse_args(argv: Sequence[str] | None = None) -> argparse.Namespace:
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(description="Ledger service")
    parser.add_argument(
        "--config",
        type=Path,
        required=True,
        help="path to the YAML configuration file",
    )
    return parser.parse_args(argv)


def main(argv: Sequence[str] | None = None) -> dict[str, object]:
    """Load the configuration named on the command line."""
    args = parse_args(argv)
    return load_config(args.config)

