from pathlib import Path

import pytest

from ledger.config import ConfigError, load_config, main


def test_loads_mapping(tmp_path: Path) -> None:
    path = tmp_path / "c.yaml"
    path.write_text("port: 8080\n")
    assert load_config(path) == {"port": 8080}


def test_empty_file_is_empty_mapping(tmp_path: Path) -> None:
    path = tmp_path / "c.yaml"
    path.write_text("")
    assert load_config(path) == {}


def test_python_object_tag_is_rejected(tmp_path: Path) -> None:
    path = tmp_path / "c.yaml"
    path.write_text("x: !!python/object/apply:os.getcwd []\n")
    with pytest.raises(ConfigError):
        load_config(path)


def test_non_mapping_is_rejected(tmp_path: Path) -> None:
    path = tmp_path / "c.yaml"
    path.write_text("- a\n- b\n")
    with pytest.raises(ConfigError):
        load_config(path)


def test_missing_file(tmp_path: Path) -> None:
    with pytest.raises(ConfigError):
        load_config(tmp_path / "nope.yaml")


def test_main_reads_config_flag(tmp_path: Path) -> None:
    path = tmp_path / "c.yaml"
    path.write_text("a: 1\n")
    assert main(["--config", str(path)]) == {"a": 1}

